const uid = $input.first().json.result;
const inicio = $now.setZone('America/Merida').startOf('day');
const fin = inicio.plus({ days: 1 });
return [{ json: {
  result: uid,
  date_from: inicio.toFormat('yyyy-MM-dd HH:mm:ss'),
  date_to: fin.toFormat('yyyy-MM-dd HH:mm:ss')
} }];

const rows = $input.first().json.result || [];
const round2 = n => Math.round((n + Number.EPSILON) * 100) / 100;

// Sumas explicitas con Number() para evitar concatenacion de strings en vez de suma.
const totalRevenue = round2(rows.reduce((sum, r) => sum + Number(r.price_total || 0), 0));
const totalQty = round2(rows.reduce((sum, r) => sum + Number(r.product_uom_qty || 0), 0));
const ordenesUnicas = new Set(rows.map(r => r.name)).size;
const ticketPromedio = ordenesUnicas > 0 ? round2(totalRevenue / ordenesUnicas) : 0; // guard contra division por cero

const porProducto = {};
for (const r of rows) {
  const key = r.product_id?.[1] ?? 'N/D';
  porProducto[key] = (porProducto[key] || 0) + Number(r.price_total || 0);
}
const topProductos = Object.entries(porProducto)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([nombre, monto]) => `• ${nombre}: $${round2(monto).toFixed(2)}`);

const text = `📊 <b>Reporte de Ventas del Dia</b>\n` +
  `Ordenes: <b>${ordenesUnicas}</b>\n` +
  `Unidades vendidas: <b>${totalQty}</b>\n` +
  `Ingreso total: <b>$${totalRevenue.toFixed(2)}</b>\n` +
  `Ticket promedio: <b>$${ticketPromedio.toFixed(2)}</b>\n\n` +
  `<b>Top 5 productos por ingreso:</b>\n${topProductos.join('\n')}`;

return [{ json: { text } }];

const err = $input.first().json;
const detalle = err.error?.message ?? err.message ?? JSON.stringify(err);
return [{ json: { text: `🔴 <b>Reporte de Ventas: fallo al autenticar contra Odoo</b>\nDetalle: <code>${detalle}</code>` } }];

